def now() -> str:
    return datetime.now().isoformat(timespec="seconds")


def add_old_text_replacements(conn) -> dict[int, str]:
    generated: dict[int, str] = {}
    for segment_id, replacements in OLD_TEXT_REPLACEMENTS.items():
        row = conn.execute(
            "SELECT old_text FROM source_segments WHERE id = ?",
            (segment_id,),
        ).fetchone()
        if not row or not row["old_text"]:
            continue
        text = row["old_text"]
        for old, new in replacements:
            text = text.replace(old, new)
        generated[segment_id] = text
    return generated


def main(apply: bool = False) -> None:
    settings = db.load_settings()
    timestamp = now()
    print("[apply_curated_residual_fixes] Starting curated residual fixes")
    print(f"[apply_curated_residual_fixes] Rule version: {RULE_VERSION}")
    print(f"[apply_curated_residual_fixes] Apply: {apply}")
    print(f"[apply_curated_residual_fixes] Database: {db.get_database_path(settings)}")

    applied = 0
    skipped_existing = 0
    token_warnings: list[str] = []
    token_mismatch_allowed: list[str] = []
    missing: list[int] = []

    with db.connect(settings) as conn:
        db.ensure_database(conn)
        corrections = dict(CORRECTIONS)
        corrections.update(add_old_text_replacements(conn))
        for segment_id, text in corrections.items():
            row = conn.execute(
                """
                SELECT s.id, s.spanish_text, sc.segment_id AS confirmed
                FROM source_segments s
                LEFT JOIN segment_confirmations sc ON sc.segment_id = s.id
                WHERE s.id = ?
                """,
                (segment_id,),
            ).fetchone()
            if not row:
                missing.append(segment_id)
                continue
            if row["confirmed"] is not None:
                skipped_existing += 1
                continue
            if protected_tokens(row["spanish_text"]) != protected_tokens(text):
                if segment_id in TOKEN_MISMATCH_ALLOWED:
                    token_mismatch_allowed.append(str(segment_id))
                else:
                    token_warnings.append(str(segment_id))
                    continue
            if apply:
                conn.execute(
                    """
                    INSERT INTO segment_confirmations (
                        segment_id, confirmation_level, confirmed_text, confirmation_source,
                        confirmation_label, locked, confidence_score, candidate_id, feedback_id,
                        reviewer, confirmed_at, updated_at
                    )
                    VALUES (?, 'human_confirmed', ?, 'curated_residual_fixes', ?, 0, 0.985, NULL, NULL, ?, ?, ?)
                    """,
                    (segment_id, text, LABEL, "codex_curated", timestamp, timestamp),
                )
            applied += 1
        if apply:
            conn.commit()

    report_lines = [
        "Apply curated residual fixes report",
        f"Started at: {timestamp}",
        f"Rule version: {RULE_VERSION}",
        "",
        "Summary:",
        f"- Corrections configured: {len(CORRECTIONS)}",
        f"- Accepted: {applied}",
        f"- Applied: {applied if apply else 0}",
        f"- Skipped existing: {skipped_existing}",
        f"- Missing segments: {len(missing)}",
        f"- Token warnings: {len(token_warnings)}",
        f"- Token mismatch allowed: {len(token_mismatch_allowed)}",
        "",
        f"Missing: {', '.join(map(str, missing)) if missing else 'none'}",
        f"Token warnings: {', '.join(token_warnings) if token_warnings else 'none'}",
        f"Token mismatch allowed: {', '.join(token_mismatch_allowed) if token_mismatch_allowed else 'none'}",
    ]
    report_path = db.write_report(settings, "apply_curated_residual_fixes", report_lines)
    print(f"[apply_curated_residual_fixes] Accepted: {applied}")
    print(f"[apply_curated_residual_fixes] Applied: {applied if apply else 0}")
    print(f"[apply_curated_residual_fixes] Skipped existing: {skipped_existing}")
    print(f"[apply_curated_residual_fixes] Missing: {len(missing)}")
    print(f"[apply_curated_residual_fixes] Token warnings: {len(token_warnings)}")
    print(f"[apply_curated_residual_fixes] Token mismatch allowed: {len(token_mismatch_allowed)}")
    print(f"[apply_curated_residual_fixes] Report: {report_path}")
    print("[apply_curated_residual_fixes] Done")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Apply curated residual corrections.")
    parser.add_argument("--apply", action="store_true", help="Write confirmations. Default is dry-run.")
    args = parser.parse_args()
    main(apply=args.apply)
